package com.tekwatt.payment.dto;import com.tekwatt.payment.entity.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;public record PaymentResponse(UUID id,UUID tenantId,UUID userId,UUID billId,UUID invoiceId,String idempotencyKey,String provider,String paymentMethod,BigDecimal amount,String currency,PaymentStatus status,String providerReference,String failureReason,Instant createdAt,Instant completedAt,Instant refundedAt,Instant updatedAt){public static PaymentResponse from(Payment p){return new PaymentResponse(p.getId(),p.getTenantId(),p.getUserId(),p.getBillId(),p.getInvoiceId(),p.getIdempotencyKey(),p.getProvider(),p.getPaymentMethod(),p.getAmount(),p.getCurrency(),p.getStatus(),p.getProviderReference(),p.getFailureReason(),p.getCreatedAt(),p.getCompletedAt(),p.getRefundedAt(),p.getUpdatedAt());}}
